    20  namespace {
    21
    22  const char *g_tokenStr[] = {
    23  #define TOK(name, str) str,
    24  #include "hermes/Parser/TokenKinds.def"
    25  };
    26
    27  const int UTF8_LINE_TERMINATOR_CHAR0 = 0xe2;
    28
    29  inline bool matchUnicodeLineTerminatorOffset1(const char *curCharPtr_) {
    30    // Line separator \u2028 UTF8 encoded is      : e2 80 a8
    31    // Paragraph separator \u2029 UTF8 encoded is: e2 80 a9
    32    return (unsigned char)curCharPtr_[1] == 0x80 &&
    33        ((unsigned char)curCharPtr_[2] == 0xa8 ||
    34         (unsigned char)curCharPtr_[2] == 0xa9);
    35  }
    36  } // namespace
    37
    38  const char *tokenKindStr(TokenKind kind) {
    39    assert(kind <= TokenKind::_last_token);
    40    return g_tokenStr[static_cast<unsigned>(kind)];
    41  }
    42  JSLexer::JSLexer(
    43      uint32_t bufId,
    44      SourceErrorManager &sm,
    45      Allocator &allocator,
    46      StringTable *strTab,
    47      bool strictMode,
    48      bool convertSurrogates)
    49      : sm_(sm),
    50        allocator_(allocator),
    51        ownStrTab_(strTab ? nullptr : new StringTable(allocator_)),
    52        strTab_(strTab ? *strTab : *ownStrTab_),
    53        strictMode_(strictMode),
    54        convertSurrogates_(convertSurrogates) {
    55    initializeWithBufferId(bufId);
    56    initializeReservedIdentifiers();
    57  }
    58
    59  JSLexer::JSLexer(
    60      std::unique_ptr<llvh::MemoryBuffer> input,
    61      SourceErrorManager &sm,
    62      Allocator &allocator,
    63      StringTable *strTab,
    64      bool strictMode,
    65      bool convertSurrogates)
    66      : sm_(sm),
    67        allocator_(allocator),
    68        ownStrTab_(strTab ? nullptr : new StringTable(allocator_)),
    69        strTab_(strTab ? *strTab : *ownStrTab_),
    70        strictMode_(strictMode),
    71        convertSurrogates_(convertSurrogates) {
    72    auto bufId = sm_.addNewSourceBuffer(std::move(input));
    73    initializeWithBufferId(bufId);
    74    initializeReservedIdentifiers();
    75  }
    76
    77  void JSLexer::initializeWithBufferId(uint32_t bufId) {
    78    auto *buffer = sm_.getSourceBuffer(bufId);
    79    bufId_ = bufId;
    80    bufferStart_ = buffer->getBufferStart();
    81    bufferEnd_ = buffer->getBufferEnd();
    82    curCharPtr_ = bufferStart_;
    83    assert(*bufferEnd_ == 0 && "buffer must be zero terminated");
    84  }
    85
    86  void JSLexer::initializeReservedIdentifiers() {
    87    // Add all reserved words to the identifier table
    88  #define RESWORD(name) resWordIdent(TokenKind::rw_##name) = getIdentifier(#name);
    89  #include "hermes/Parser/TokenKinds.def"
    90  }
    91
    92  const Token *JSLexer::advance(GrammarContext grammarContext) {
    93    newLineBeforeCurrentToken_ = false;
    94
    95    for (;;) {
    96      assert(curCharPtr_ <= bufferEnd_ && "lexing past end of input");
    97  #define PUNC_L1_1(ch, tok)        \
    98    case ch:                        \
    99      token_.setStart(curCharPtr_); \
   100      token_.setPunctuator(tok);    \
   101      ++curCharPtr_;                \
   102      break
   103
   104  #define PUNC_L2_3(ch1, tok1, ch2a, tok2a, ch2b, tok2b) \
   105    case ch1:                                            \
   106      token_.setStart(curCharPtr_);                      \
   107      if (curCharPtr_[1] == ch2a) {                      \
   108        token_.setPunctuator(tok2a);                     \
   109        curCharPtr_ += 2;                                \
   110      } else if (curCharPtr_[1] == ch2b) {               \
   111        token_.setPunctuator(tok2b);                     \
   112        curCharPtr_ += 2;                                \
   113      } else {                                           \
   114        token_.setPunctuator(tok1);                      \
   115        curCharPtr_ += 1;                                \
   116      }                                                  \
   117      break
   118
   119  #define PUNC_L2_2(ch1, tok1, ch2, tok2) \
   120    case ch1:                             \
   121      token_.setStart(curCharPtr_);       \
   122      if (curCharPtr_[1] == (ch2)) {      \
   123        token_.setPunctuator(tok2);       \
   124        curCharPtr_ += 2;                 \
   125      } else {                            \
   126        token_.setPunctuator(tok1);       \
   127        curCharPtr_ += 1;                 \
   128      }                                   \
   129      break
   130
   131  #define PUNC_L3_3(ch1, tok1, ch2, tok2, ch3, tok3) \
   132    case ch1:                                        \
   133      token_.setStart(curCharPtr_);                  \
   134      if (curCharPtr_[1] != (ch2)) {                 \
   135        token_.setPunctuator(tok1);                  \
   136        curCharPtr_ += 1;                            \
   137      } else if (curCharPtr_[2] == (ch3)) {          \
   138        token_.setPunctuator(tok3);                  \
   139        curCharPtr_ += 3;                            \
   140      } else {                                       \
   141        token_.setPunctuator(tok2);                  \
   142        curCharPtr_ += 2;                            \
   143      }                                              \
   144      break
   145
   146      switch ((unsigned char)*curCharPtr_) {
   147        case 0:
   148          token_.setStart(curCharPtr_);
   149          if (curCharPtr_ == bufferEnd_) {
   150            token_.setEof();
   150            token_.setEof();
   151          } else {
   152            if (!error(
   153                    token_.getStartLoc(),
   154                    "unrecognized Unicode character \\u0000")) {
   155              token_.setEof();
   156            } else {
   157              ++curCharPtr_;
   158              continue;
   159            }
   160          }
   161          break;
   162
   163          // clang-format off
   164        PUNC_L1_1('}', TokenKind::r_brace);
   165        PUNC_L1_1('(', TokenKind::l_paren);
   166        PUNC_L1_1(')', TokenKind::r_paren);
   167        PUNC_L1_1('[', TokenKind::l_square);
   168        PUNC_L1_1(']', TokenKind::r_square);
   169        PUNC_L1_1(';', TokenKind::semi);
   170        PUNC_L1_1(',', TokenKind::comma);
   171        PUNC_L1_1('~', TokenKind::tilde);
   172        PUNC_L1_1(':', TokenKind::colon);
   173
   174        // { {|
   175        case '{':
   176          token_.setStart(curCharPtr_);
   177          if (HERMES_PARSE_FLOW &&
   178              LLVM_UNLIKELY(grammarContext == GrammarContext::Flow) &&
   179              curCharPtr_[1] == '|') {
   180            token_.setPunctuator(TokenKind::l_bracepipe);
   181            curCharPtr_ += 2;
   182          } else {
   183            token_.setPunctuator(TokenKind::l_brace);
   184            curCharPtr_ += 1;
   185          }
   186          break;
   187
   188        // = => == ===
   189        case '=':
   190          token_.setStart(curCharPtr_);
   191          if (curCharPtr_[1] == '>') {
   192            token_.setPunctuator(TokenKind::equalgreater);
   193            curCharPtr_ += 2;
   194          } else if (curCharPtr_[1] != '=') {
   195            token_.setPunctuator(TokenKind::equal);
   196            curCharPtr_ += 1;
   197          } else if (curCharPtr_[2] == '=') {
   198            token_.setPunctuator(TokenKind::equalequalequal);
   199            curCharPtr_ += 3;
   200          } else {
   201            token_.setPunctuator(TokenKind::equalequal);
   202            curCharPtr_ += 2;
   203          }
   204          break;
   205
   206        // ! != !==
   207        PUNC_L3_3('!', TokenKind::exclaim, '=', TokenKind::exclaimequal, '=', TokenKind::exclaimequalequal);
   208
   209        // + ++ +=
   210        // - -- -=
   211        // & && &=
   212        // | || |=
   213        PUNC_L2_3('+', TokenKind::plus,  '+', TokenKind::plusplus,   '=', TokenKind::plusequal);
   214        PUNC_L2_3('-', TokenKind::minus, '-', TokenKind::minusminus, '=', TokenKind::minusequal);
   215
   216        case '&':
   217          token_.setStart(curCharPtr_);
   218          if (curCharPtr_[1] == '&') {
   219            if (curCharPtr_[2] == '=') {
   220              token_.setPunctuator(TokenKind::ampampequal);
   221              curCharPtr_ += 3;
   222            } else {
   223              token_.setPunctuator(TokenKind::ampamp);
   224              curCharPtr_ += 2;
   225            }
   226          } else if (curCharPtr_[1] == '=') {
   227            token_.setPunctuator(TokenKind::ampequal);
   228            curCharPtr_ += 2;
   229          } else {
   230            token_.setPunctuator(TokenKind::amp);
   231            curCharPtr_ += 1;
   232          }
   233          break;
   234
   235        case '|':
   236          token_.setStart(curCharPtr_);
   237          if (HERMES_PARSE_FLOW &&
   238              LLVM_UNLIKELY(grammarContext == GrammarContext::Flow) &&
   239              curCharPtr_[1] == '}') {
   240            token_.setPunctuator(TokenKind::piper_brace);
   241            curCharPtr_ += 2;
   242          } else {
   243            if (curCharPtr_[1] == '|') {
   244              if (curCharPtr_[2] == '=') {
   245                token_.setPunctuator(TokenKind::pipepipeequal);
   246                curCharPtr_ += 3;
   247              } else {
   248                token_.setPunctuator(TokenKind::pipepipe);
   249                curCharPtr_ += 2;
   250              }
   251            } else if (curCharPtr_[1] == '=') {
   252              token_.setPunctuator(TokenKind::pipeequal);
   253              curCharPtr_ += 2;
   254            } else {
   255              token_.setPunctuator(TokenKind::pipe);
   256              curCharPtr_ += 1;
   257            }
   258          }
   259          break;
   260
   261        // ? ?? ?.
   262        case '?':
   263          token_.setStart(curCharPtr_);
   264          if (HERMES_PARSE_FLOW &&
   265              LLVM_UNLIKELY(grammarContext == GrammarContext::Flow)) {
   266            token_.setPunctuator(TokenKind::question);
   267            curCharPtr_ += 1;
   268          } else if (curCharPtr_[1] == '.' && !isdigit(curCharPtr_[2])) {
   269            // OptionalChainingPunctuator ::
   270            // ?. [lookahead does not contain DecimalDigit]
   271            // This is done to prevent `x?.3:y` from being recognized
   272            // as `x ?. 3 : y` instead of `x ? .3 : y`.
   273            token_.setPunctuator(TokenKind::questiondot);
   274            curCharPtr_ += 2;
   275          } else if (curCharPtr_[1] == '?') {
   276            if (curCharPtr_[2] == '=') {
   277              token_.setPunctuator(TokenKind::questionquestionequal);
   278              curCharPtr_ += 3;
   279            } else {
   280              token_.setPunctuator(TokenKind::questionquestion);
   281              curCharPtr_ += 2;
   282            }
   283          } else {
   284            token_.setPunctuator(TokenKind::question);
   285            curCharPtr_ += 1;
   286          }
   287          break;
   288
   289        // * *= ** **=
   290        case '*':
   291          token_.setStart(curCharPtr_);
   292          if (curCharPtr_[1] == '=') {
   293            token_.setPunctuator(TokenKind::starequal);
   294            curCharPtr_ += 2;
   295          } else if (curCharPtr_[1] != '*') {
   296            token_.setPunctuator(TokenKind::star);
   297            curCharPtr_ += 1;
   298          } else if (curCharPtr_[2] == '=') {
   299            token_.setPunctuator(TokenKind::starstarequal);
   300            curCharPtr_ += 3;
   301          } else {
   302            token_.setPunctuator(TokenKind::starstar);
   303            curCharPtr_ += 2;
   304          }
   305          break;
   306
   307        // * *=
   308        // ^ ^=
   309        // / /=
   310        PUNC_L2_2('^', TokenKind::caret, '=', TokenKind::caretequal);
   311
   312        // % %=
   313        case '%':
   314        token_.setStart(curCharPtr_);
   315          if (HERMES_PARSE_FLOW &&
   316              LLVM_UNLIKELY(grammarContext == GrammarContext::Flow) &&
   317              llvh::StringRef(curCharPtr_, 7) == "%checks") {
   318            token_.setIdentifier(getStringLiteral("%checks"));
   319            curCharPtr_ += 7;
   320          } else if (curCharPtr_[1] == ('=')) {
   321            token_.setPunctuator(TokenKind::percentequal);
   322            curCharPtr_ += 2;
   323          } else {
   324            token_.setPunctuator(TokenKind::percent);
   325            curCharPtr_ += 1;
   326          }
   327          break;
   328
   329          // clang-format on
   330
   331        case '\r':
   332        case '\n':
   333          ++curCharPtr_;
   334          newLineBeforeCurrentToken_ = true;
   335          continue;
   336
   337        // Line separator \u2028 UTF8 encoded is      : e2 80 a8
   338        // Paragraph separator \u2029 UTF8 encoded is : e2 80 a9
   339        case UTF8_LINE_TERMINATOR_CHAR0:
   340          if (matchUnicodeLineTerminatorOffset1(curCharPtr_)) {
   341            curCharPtr_ += 3;
   342            newLineBeforeCurrentToken_ = true;
   343            continue;
   344          } else {
   345            goto default_label;
   346          }
   347
   348        case '\v':
   349        case '\f':
   350          ++curCharPtr_;
   351          continue;
   352
   353        case '\t':
   354        case ' ':
   355          // Spaces frequently come in groups, so use a tight inner loop to skip.
   356          do
   357            ++curCharPtr_;
   358          while (*curCharPtr_ == '\t' || *curCharPtr_ == ' ');
   359          continue;
   360
   361        // No-break space \u00A0 is UTF8 encoded as: c2 a0
   362        case 0xc2:
   363          if ((unsigned char)curCharPtr_[1] == 0xa0) {
   364            curCharPtr_ += 2;
   365            continue;
   366          } else {
   367            goto default_label;
   368          }
   369
   370        // Byte-order mark \uFEFF is encoded as: ef bb bf
   371        case 0xef:
   372          if ((unsigned char)curCharPtr_[1] == 0xbb &&
   373              (unsigned char)curCharPtr_[2] == 0xbf) {
   374            curCharPtr_ += 3;
   375            continue;
   376          } else {
   377            goto default_label;
   378          }
   379
   380        case '/':
   381          if (curCharPtr_[1] == '/') { // Line comment?
   382            if (LLVM_UNLIKELY(curCharPtr_[2] == '#')) {
   383              if (auto sourceMappingUrl =
   384                      tryReadMagicComment("sourceMappingURL", curCharPtr_)) {
   385                sm_.setSourceMappingUrl(bufId_, sourceMappingUrl.getValue());
   386              } else if (
   387                  auto sourceUrl =
   388                      tryReadMagicComment("sourceURL", curCharPtr_)) {
   389                sm_.setSourceUrl(bufId_, sourceUrl.getValue());
   390              }
   391            }
   392            curCharPtr_ = skipLineComment(curCharPtr_);
   393            continue;
   394          } else if (curCharPtr_[1] == '*') { // Block comment?
   395            curCharPtr_ = skipBlockComment(curCharPtr_);
   396            continue;
   397          } else {
   398            token_.setStart(curCharPtr_);
   399            if (grammarContext == AllowRegExp) {
   400              scanRegExp();
   401            } else if (curCharPtr_[1] == '=') {
   402              token_.setPunctuator(TokenKind::slashequal);
   403              curCharPtr_ += 2;
   404            } else {
   405              token_.setPunctuator(TokenKind::slash);
   406              curCharPtr_ += 1;
   407            }
   408          }
   409          break;
   410
   411        // #! (hashbang) at the very start of the buffer.
   412        case '#':
   413          if (LLVM_UNLIKELY(
   414                  curCharPtr_ == bufferStart_ && curCharPtr_[1] == '!')) {
   415            curCharPtr_ = skipLineComment(curCharPtr_);
   416            continue;
   417          } else {
   418            goto default_label;
   419          }
   420
   421        // <  <= << <<=
   422        case '<':
   423          token_.setStart(curCharPtr_);
   424          if (HERMES_PARSE_FLOW &&
   425              LLVM_UNLIKELY(grammarContext == JSLexer::GrammarContext::Flow)) {
   426            token_.setPunctuator(TokenKind::less);
   427            curCharPtr_ += 1;
   428          } else if (curCharPtr_[1] == '=') {
   429            token_.setPunctuator(TokenKind::lessequal);
   430            curCharPtr_ += 2;
   431          } else if (curCharPtr_[1] == '<') {
   432            if (curCharPtr_[2] == '=') {
   433              token_.setPunctuator(TokenKind::lesslessequal);
   434              curCharPtr_ += 3;
   435            } else {
   436              token_.setPunctuator(TokenKind::lessless);
   437              curCharPtr_ += 2;
   438            }
   439          } else {
   440            token_.setPunctuator(TokenKind::less);
   441            curCharPtr_ += 1;
   442          }
   443          break;
   444
   445        // > >= >> >>> >>= >>>=
   446        case '>':
   447          token_.setStart(curCharPtr_);
   448          if ((HERMES_PARSE_FLOW &&
   449               LLVM_UNLIKELY(grammarContext == JSLexer::GrammarContext::Flow)) ||
   450              (HERMES_PARSE_JSX &&
   451               LLVM_UNLIKELY(
   452                   grammarContext ==
   453                   JSLexer::GrammarContext::AllowJSXIdentifier))) {
   454            token_.setPunctuator(TokenKind::greater);
   455            curCharPtr_ += 1;
   456          } else if (curCharPtr_[1] == '=') { // >=
   457            token_.setPunctuator(TokenKind::greaterequal);
   458            curCharPtr_ += 2;
   459          } else if (curCharPtr_[1] == '>') { // >>
   460            if (curCharPtr_[2] == '=') { // >>=
   461              token_.setPunctuator(TokenKind::greatergreaterequal);
   462              curCharPtr_ += 3;
   463            } else if (curCharPtr_[2] == '>') { // >>>
   464              if (curCharPtr_[3] == '=') { // >>>=
   465                token_.setPunctuator(TokenKind::greatergreatergreaterequal);
   466                curCharPtr_ += 4;
   467              } else {
   468                token_.setPunctuator(TokenKind::greatergreatergreater);
   469                curCharPtr_ += 3;
   470              }
   471            } else {
   472              token_.setPunctuator(TokenKind::greatergreater);
   473              curCharPtr_ += 2;
   474            }
   475          } else {
   476            token_.setPunctuator(TokenKind::greater);
   477            curCharPtr_ += 1;
   478          }
   479          break;
   480
   481        case '.':
   482          token_.setStart(curCharPtr_);
   483          if (curCharPtr_[1] >= '0' && curCharPtr_[1] <= '9') {
   484            scanNumber();
   485          } else if (curCharPtr_[1] == '.' && curCharPtr_[2] == '.') {
   486            token_.setPunctuator(TokenKind::dotdotdot);
   487            curCharPtr_ += 3;
   488          } else {
   489            token_.setPunctuator(TokenKind::period);
   490            ++curCharPtr_;
   491          }
   492          break;
   493
   494          // clang-format off
   495        case '0': case '1': case '2': case '3': case '4':
   496        case '5': case '6': case '7': case '8': case '9':
   497          // clang-format on
   498          token_.setStart(curCharPtr_);
   499          scanNumber();
   500          break;
   501
   502          // clang-format off
   503        case '_': case '$':
   504        case 'a': case 'b': case 'c': case 'd': case 'e': case 'f': case 'g':
   505        case 'h': case 'i': case 'j': case 'k': case 'l': case 'm': case 'n':
   506        case 'o': case 'p': case 'q': case 'r': case 's': case 't': case 'u':
   507        case 'v': case 'w': case 'x': case 'y': case 'z':
   508        case 'A': case 'B': case 'C': case 'D': case 'E': case 'F': case 'G':
   509        case 'H': case 'I': case 'J': case 'K': case 'L': case 'M': case 'N':
   510        case 'O': case 'P': case 'Q': case 'R': case 'S': case 'T': case 'U':
   511        case 'V': case 'W': case 'X': case 'Y': case 'Z':
   512          // clang-format on
   513          token_.setStart(curCharPtr_);
   514          scanIdentifierFastPathInContext(curCharPtr_, grammarContext);
   515          break;
   516
   517        case '@':
   518          token_.setStart(curCharPtr_);
   519          if (HERMES_PARSE_FLOW &&
   520              LLVM_UNLIKELY(grammarContext == GrammarContext::Flow)) {
